import{c as i,Z as n,Q as p,j as e,m as s,g as l,n as a,o as r,av as d}from"./chunks/framework.rWdQudnF.js";const y=JSON.parse('{"title":"文件管理基础","description":"","frontmatter":{"title":"文件管理基础"},"headers":[],"relativePath":"综合知识/系统基础/操作系统/文件管理基础.md","filePath":"综合知识/系统基础/操作系统/文件管理基础.md","lastUpdated":null}'),c={name:"综合知识/系统基础/操作系统/文件管理基础.md"};function u(g,t,h,b,m,k){const o=n("font");return p(),e("div",null,[t[5]||(t[5]=s('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 文件逻辑结构与物理结构</li><li>[x] 存取方法（顺序/随机）</li><li>[x] 文件属性（R/A/S/H）</li><li>[x] 存取控制与硬链接</li><li>[x] 链式存储与成组分解</li><li>[x] 位示图</li><li>[x] 文件存储空间管理</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="文件概述" tabindex="-1">文件概述 <a class="header-anchor" href="#文件概述" aria-label="Permalink to &quot;文件概述&quot;">​</a></h3><p>文件的逻辑结构：有结构的记录式文件、无结构的流式文件。</p><p>文件的物理结构（在物理存储设备上的存放方法）：</p><table tabindex="0"><thead><tr><th>结构</th><th>特点</th><th>随机访问</th></tr></thead><tbody><tr><td>连续结构</td><td>逻辑连续的文件信息依次存放在连续物理块上</td><td>✅ 快 O(1)</td></tr><tr><td>链接结构</td><td>存放在不连续物理块，每块末尾有指针指向下一块（指针散落在数据块中）</td><td>❌ 慢 O(N)</td></tr><tr><td>索引结构</td><td>存放在不连续物理块，系统建立索引表集中记录逻辑块号→物理块号映射</td><td>✅ 快 O(1)</td></tr><tr><td>多级索引</td><td>索引表占用一个或多个物理块（直接/一级间接/二级间接）</td><td>✅ 但多一级间接多一次读盘</td></tr></tbody></table><blockquote><p>⚠️ 文件物理结构<strong>不包括散列结构</strong>。连续结构支持快速随机访问但<strong>易产生碎片</strong>。</p></blockquote><p>💡 <strong>链接 vs 索引核心区别</strong>：</p>',9)),l("ul",null,[l("li",null,[t[1]||(t[1]=l("strong",null,"链接结构",-1)),t[2]||(t[2]=a(" = ",-1)),r(o,{color:"#4bacc6"},{default:d(()=>[...t[0]||(t[0]=[a("指针分散",-1)])]),_:1}),t[3]||(t[3]=a("在各数据块中，像寻宝线索逐块跟 → 随机读慢",-1))]),t[4]||(t[4]=l("li",null,[l("strong",null,"索引结构"),a(" = "),l("u",null,"映射关系集中在一张索引表"),a("，查表即得 → 随机读快")],-1))]),t[6]||(t[6]=s(`<p>类比：链接 = 糖葫芦串，索引 = 字典检字表。</p><p>存取方法：顺序存取、随机存取。</p><blockquote><p>⚠️ 顺序存取的效率<strong>不一定</strong>高于随机存取，取决于实际场景。文件可同时支持两种存取方式。</p></blockquote><h3 id="索引文件结构" tabindex="-1">索引文件结构 <a class="header-anchor" href="#索引文件结构" aria-label="Permalink to &quot;索引文件结构&quot;">​</a></h3><p>详见：<a href="/arch-exam/综合知识/系统基础/操作系统/索引文件结构.html">架构师-备考 综合知识-系统基础-操作系统-索引文件结构</a></p><h3 id="文件目录" tabindex="-1">文件目录 <a class="header-anchor" href="#文件目录" aria-label="Permalink to &quot;文件目录&quot;">​</a></h3><p>详见：<a href="/arch-exam/综合知识/系统基础/操作系统/文件目录.html">架构师-备考 综合知识-系统基础-操作系统-文件目录</a></p><h3 id="文件属性" tabindex="-1">文件属性 <a class="header-anchor" href="#文件属性" aria-label="Permalink to &quot;文件属性&quot;">​</a></h3><blockquote><p>🎯 一句话结论：R=只读、A=归档、S=系统文件、H=隐藏。</p></blockquote><p><strong>文件属性</strong>，对应 Windows 文件系统中的四个基本属性，缩写的来源：</p><table tabindex="0"><thead><tr><th>属性</th><th>英文</th><th>含义</th></tr></thead><tbody><tr><td><strong>R</strong></td><td>Read-only</td><td>只读文件</td></tr><tr><td><strong>A</strong></td><td>Archive</td><td>归档文件（标记需要备份）</td></tr><tr><td><strong>S</strong></td><td>System</td><td><strong>系统文件</strong></td></tr><tr><td><strong>H</strong></td><td>Hidden</td><td>隐藏文件</td></tr></tbody></table><h3 id="存取控制" tabindex="-1">存取控制 <a class="header-anchor" href="#存取控制" aria-label="Permalink to &quot;存取控制&quot;">​</a></h3><blockquote><p>🎯 一句话结论：密码保护<strong>不属于</strong>存取控制类型。</p></blockquote><p><strong>存取控制类型</strong>：存取控制矩阵、存取控制表、用户权限表。⚠️ <strong>密码保护</strong>不属于存取控制类型（属于密码保护类型）。</p><h3 id="硬链接与软链接" tabindex="-1">硬链接与软链接 <a class="header-anchor" href="#硬链接与软链接" aria-label="Permalink to &quot;硬链接与软链接&quot;">​</a></h3><blockquote><p>🎯 一句话结论：硬链接=共享 inode（引数器 +1），软链接=存路径（快捷方式）。</p></blockquote><p><strong>硬链接（Hard Link）</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目录项「a.txt」 ──→ inode #100 ──→ 数据块</span></span>
<span class="line"><span>目录项「a_hard」──→ inode #100 ──→ 数据块（同一个 inode）</span></span></code></pre></div><ul><li>本质：两个目录项指向<strong>同一个 inode</strong></li><li>理解成 <strong>inode 的引数器（nlink）+1</strong>。每次 <code>rm</code> 只是引数器 -1，并不删除数据。只有引数器归零才真正释放数据块。</li><li>所有目录项地位平等，不存在&quot;原文件&quot;和&quot;链接文件&quot;之分</li><li>❌ 不能跨文件系统</li><li>❌ 不能指向目录（通常不允许）</li><li>类比：同一个人有多个名字，叫哪个名字都找到同一个人</li></ul><p><strong>软链接 / 符号链接（Symbolic Link）</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>软链接「a_soft」──→ inode #200 ──→ 路径字符串「/data/a.txt」</span></span>
<span class="line"><span>                                             ↓</span></span>
<span class="line"><span>                                       /data/a.txt ──→ inode #100 ──→ 数据块</span></span></code></pre></div><ul><li>本质：单独占用一个 inode，里面存的是<strong>目标文件的路径字符串</strong></li><li>不操作目标文件的引数器，两者独立</li><li>删除原文件后 → 软链接变为<strong>死链接（dangling link）</strong>，无法访问</li><li>✅ 可以跨文件系统</li><li>✅ 可以指向目录</li><li>类比：一张写着地址的纸条，房子拆了纸条还在但去了找不到</li></ul><p><strong>引数器理解法（核心）</strong></p><blockquote><p>硬链接操作 inode 引数器（nlink）：创建 → +1，删除 → -1，归零 → 真正释放。<br> 软链接不操作目标文件的引数器，删原文件与软链接无关。</p></blockquote><h3 id="链式存储与成组分解" tabindex="-1">链式存储与成组分解 <a class="header-anchor" href="#链式存储与成组分解" aria-label="Permalink to &quot;链式存储与成组分解&quot;">​</a></h3><blockquote><p>🎯 一句话结论：成组分解 = 多记录打包存入一块；读取时先读块再分解出目标记录。</p></blockquote><p>链式存储中，物理块不连续，每块有指针指向下一块。<strong>成组分解技术</strong>：多个逻辑记录打包存入一个物理块；读取时先将物理块读入缓冲区，再分解出目标记录。</p><blockquote><p>计算：磁盘块 4096 字节，记录 2048 字节 → 每块存 2 个记录。访问第 12288 字节 → 12288 / 4096 = <strong>第 3 个磁盘块</strong>（从 0 计数）。</p></blockquote><h3 id="位示图" tabindex="-1">位示图 <a class="header-anchor" href="#位示图" aria-label="Permalink to &quot;位示图&quot;">​</a></h3><blockquote><p>🎯 一句话结论：位示图每一位对应一个物理块，1 = 已占用，0 = 空闲。用于管理磁盘空闲块。</p></blockquote><blockquote><p>💡 <strong>本质理解</strong>：磁盘有 N 个物理块，操作系统需要知道哪些块空闲。最朴素的方式是列空闲块列表，但磁盘上亿个块太占空间。位示图的思路是<strong>每个物理块只占 1 个 bit（比特）</strong>，0=空闲，1=已占用，bit 位置与物理块号一一映射。</p></blockquote><p>位 = bit（比特），示图 = map（映射图）——「用比特位标示磁盘块状态的图」。</p><p>它与「索引结构」的区别：<strong>位示图管全盘空闲空间</strong>（回答&quot;新文件放哪&quot;），<strong>索引结构管单个文件</strong>（回答&quot;这个文件的块在哪&quot;）。</p><p><strong>算例</strong>：磁盘 100 个物理块，每块 1KB，字长 32 位（编号均从0开始）。要找物理块 66 是否空闲：</p><p><strong>前提约定（考题惯例）：字号和位号都从 0 开始计数。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>字0（第1个字）→ 位0~位31 → 物理块 0~31</span></span>
<span class="line"><span>字1（第2个字）→ 位0~位31 → 物理块 32~63</span></span>
<span class="line"><span>字2（第3个字）→ 位0~位31 → 物理块 64~95</span></span></code></pre></div><p><strong>物理块 66 的位置：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>66 ÷ 32 = 2 余 2</span></span>
<span class="line"><span>         ↑     ↑</span></span>
<span class="line"><span>       字号   位号</span></span></code></pre></div><p>所以：</p><ul><li><p><strong>字号 = 2</strong> → 对应的是 <strong>字 2</strong>（从0数的第3个字）</p></li><li><p><strong>位号 = 2</strong> → 对应的是 <strong>第 2 位</strong>（从0数的第3位）</p></li><li><p>字号 = ⌊66 / 32⌋ = <strong>2</strong>（第3个字，从0计）</p></li><li><p>位号 = 66 mod 32 = <strong>2</strong>（第3位，从0计）</p></li><li><p>在位示图字2位2处查 0/1</p></li></ul><hr><h3 id="文件存储空间管理" tabindex="-1">文件存储空间管理 <a class="header-anchor" href="#文件存储空间管理" aria-label="Permalink to &quot;文件存储空间管理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>原理</th></tr></thead><tbody><tr><td>空闲区表</td><td>为每个连续空闲区建立表项，适用于连续文件结构</td></tr><tr><td>位示图 (Bitmap)</td><td>每一位对应一个物理块，0=空闲，1=占用</td></tr><tr><td>空闲块链</td><td>每个空闲块指向下一个空闲块，链表头指针放在特定位置</td></tr><tr><td>成组链接法</td><td>空闲块分组（如 100 块/组），每组第一块登记下一组盘块号和空闲块总数</td></tr></tbody></table><blockquote><p><strong>位示图计算</strong>：物理块号 N 在第 <code>⌊N/字长⌋</code> 个字中描述（从 0 编号即为第 <code>⌊N/字长⌋</code> 个字）。磁盘容量/物理块大小 = 物理块总数 → 除以字长 = 位示图所需字数。</p></blockquote><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><blockquote><p>⭐ <strong>经典题目</strong> — 链式存储+成组分解字节定位易错（块号从0计数，整除为边界）</p></blockquote><p><strong>[Q20] 链式存储+成组分解</strong></p><p>某文件系统采用链式存储管理方式并应用记录的成组与分解技术，且磁盘块的大小为 4096 字节。若文件 license.doc 由 7 个逻辑记录组成，每个逻辑记录的大小为 2048字节，并依次存放在 58、89、96 和 101 号磁盘块上，那么要存取文件的第 12288 逻辑字节处的信息，应访问（ ）号磁盘块。</p><ul><li>A. 58</li><li>B. 89</li><li>C. 96</li><li>D. 101</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：每块存2个记录(4096/2048=2)。12288/4096=3，第3块(从0计)→101号块。</p><p><strong>已知条件：</strong></p><ul><li>磁盘块大小 = <strong>4096 字节</strong></li><li>每个逻辑记录 = <strong>2048 字节</strong></li><li>所以 <strong>每块存 2 个记录</strong>（4096 ÷ 2048 = 2）</li><li>文件存于 4 个盘块（链式）：<code>58 → 89 → 96 → 101</code></li></ul><p><strong>目标：访问逻辑字节 12288</strong></p><p><strong>第一步：确定在第几个磁盘块</strong></p><p>每块 4096 字节，用逻辑字节数除以块大小：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>12288 ÷ 4096 = 3 （整除，无余数）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>块号（从0计）</th><th>字节范围</th><th>物理块</th></tr></thead><tbody><tr><td>第0块</td><td>0 ~ 4095</td><td>58</td></tr><tr><td>第1块</td><td>4096 ~ 8191</td><td>89</td></tr><tr><td>第2块</td><td>8192 ~ 12287</td><td>96</td></tr><tr><td><strong>第3块</strong></td><td><strong>12288 ~ 16383</strong></td><td><strong>101</strong></td></tr></tbody></table><p>12288 正好是第 3 块的起始位置（第0块是 0~4095 别忘了）。</p><p><strong>第二步：链式存储 → 逐块跟踪</strong></p><p>链式存储下物理块不连续，靠指针串联：</p><ul><li>文件第1块 → 58</li><li>第2块 → 89（58指向89）</li><li>第3块 → 96（89指向96）</li><li><strong>第4块 → 101</strong>（96指向101）</li></ul><p>所以第 3 块（从0计）对应物理块 <strong>101</strong>。</p><p>简单说：12288 ÷ 4096 = 3 → 第 3 块（0-indexed）→ 链式第四个节点 → <strong>101</strong></p></div></details><hr><p><strong>[Q49] 位示图</strong></p><p>文件系统中，位示图（Bitmap）的作用是（ ）。</p><ul><li>A. 记录文件的创建时间</li><li>B. 索引文件内容</li><li>C. 存储文件的访问权限</li><li>D. 管理磁盘空闲块</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：位示图每一位对应一个物理块，标记占用/空闲，用于管理磁盘空闲空间。</p></div></details><hr><p><strong>[Q52] 物理结构类型</strong></p><p>在文件系统中，用于表示文件物理结构的类型不包括（ ）。</p><ul><li>A. 连续结构</li><li>B. 链接结构</li><li>C. 索引结构</li><li>D. 散列结构</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：文件物理结构三种：连续、链接、索引。散列/哈希不是文件物理结构。</p></div></details><hr><p><strong>[Q57] 连续结构</strong></p><p>（ ）文件组织方式支持快速随机访问但易产生碎片。</p><ul><li>A. 连续结构</li><li>B. 链接结构</li><li>C. 索引结构</li><li>D. 哈希结构</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：A</p><p>解析：连续结构=文件块连续存放→随机访问快；但增删文件易产生外碎片。</p></div></details><hr><p><strong>[Q59] 文件属性</strong></p><p>在文件管理系统中，以下哪个文件属性表示该文件是一个系统文件（ ）。</p><ul><li>A. R</li><li>B. A</li><li>C. S</li><li>D. H</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：R=只读(Read-only)，A=归档(Archive)，S=系统(System)，H=隐藏(Hidden)。</p></div></details><hr><p><strong>[Q84] 存取控制</strong></p><p>下列哪种文件保护方式不属于存取控制类型（ ）。</p><ul><li>A. 存取控制矩阵</li><li>B. 存取控制表</li><li>C. 用户权限表</li><li>D. 密码保护</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：密码保护属于加密保护，不是存取控制。存取控制=矩阵/ACL/权限表。</p></div></details><hr><p><strong>[Q85] 硬链接</strong></p><p>关于文件的硬链接，下列描述正确的是（ ）。</p><ul><li>A. 创建新的文件实体</li><li>B. 两个文件目录项指向同一个索引节点</li><li>C. 建立文件路径的映射关系</li><li>D. 必须位于同一个文件系统</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：B</p><p>解析：硬链接=多个目录项指向同一inode，不创建新实体，共享同一索引节点。</p><p>D 的描述也是对的，不过更多是约束条件，选择B描述更准确一些。</p></div></details><hr><p><strong>[Q86] 存取方法</strong></p><p>关于文件的存取方法，下列说法错误的是（ ）。</p><ul><li>A. 顺序存取是按顺序依次进行读写</li><li>B. 随机存取可以按任意次序读写</li><li>C. 顺序存取的效率总是高于随机存取</li><li>D. 文件可以同时支持两种存取方式</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：顺序存取不一定总比随机快。对于索引结构/直接访问场景，随机存取可能更快。</p></div></details><hr><p><strong>[Q87] 位示图取值</strong></p><p>在位示图法中，每一位对应一个物理块，当某位取值为1时表示（ ）。</p><ul><li>A. 该物理块空闲</li><li>B. 该物理块已占用</li><li>C. 该物理块损坏</li><li>D. 该物理块未初始化</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：B</p><p>解析：位示图中 1=已占用，0=空闲。</p></div></details><hr><p><strong>[Q88] 连续结构</strong></p><p>关于文件的连续结构（顺序结构），下列说法正确的是（ ）。</p><ul><li>A. 文件信息存放在不连续的物理块上</li><li>B. 每个物理块需要指针指向下一块</li><li>C. 需要建立索引表</li><li>D. 文件信息存放在连续编号的物理块上</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：连续结构=文件块在磁盘上连续编号存放，无需指针和索引。</p></div></details><hr><p><strong>[Q89] 逻辑结构</strong></p><p>关于文件的逻辑结构，下列说法错误的是（ ）。</p><ul><li>A. 分为记录式文件和流式文件</li><li>B. 用户只需知道文件名就可以存取文件</li><li>C. 用户必须知道文件在磁盘上的物理位置</li><li>D. 记录式文件是有结构的文件</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：逻辑结构对用户透明，用户只需文件名，不需要知道物理位置。</p></div></details>`,100))])}const v=i(c,[["render",u]]);export{y as __pageData,v as default};
